SymbolDefinition.BlockNameFormat:
NO-BN-2D-JBTSA_FIK
{% if Variant == 'Via point for control panel' %}VIAPUNKT
{% else %}FIKTIVT-SLUTTPUNKT
{% endif %}
{{SymbolMode}}

Rotation.AddAngle:
{% if dir == 'up' %}{{270.0|plus:AngularOffset}}
														{% elsif dir == 'down' %}{{90.0|plus:AngularOffset}}
														{% elsif dir == 'both' and RightSided %}{{180.0|plus:AngularOffset}}
														{% elsif dir == 'both' and LeftSided %}{{0.0|plus:AngularOffset}}
														{% elsif dir == 'none' and RightSided %}{{0.0|plus:AngularOffset}}
														{% elsif dir == 'none' and LeftSided %}{{180.0|plus:AngularOffset}}
														{% else %}45.0
														{% endif %}

SymbolDefinition.BlockNameFormat:
NO-BN-2D-JBTSA_SIG-SIGNAL
{% if Variant == 'E35 Stop sign, side of track' %}
	{% if RightSided and dir == 'up' %}ERTMS-E35-HSIDE
	{% elsif LeftSided and dir == 'down' %}ERTMS-E35-HSIDE
	{% else %}ERTMS-E35-VSIDE
	{% endif %}
{% elsif Variant == 'E35 Stop sign, above track' %}ERTMS-E35-OVER
{% endif %}
{% if PortalMounted %}AAK{% endif %}
{{SymbolMode}}

Rotation.AddAngle:
{% if dir == 'up' %}{{270.0|plus:AngularOffset}}
														{% elsif dir == 'down' %}{{90.0|plus:AngularOffset}}
														{% elsif dir == 'both' and RightSided %}{{180.0|plus:AngularOffset}}
														{% elsif dir == 'both' and LeftSided %}{{0.0|plus:AngularOffset}}
														{% elsif dir == 'none' and RightSided %}{{0.0|plus:AngularOffset}}
														{% elsif dir == 'none' and LeftSided %}{{180.0|plus:AngularOffset}}
														{% else %}45.0
														{% endif %}

{% if dir == 'up' %}{{270.0|plus:AngularOffset}}
														{% elsif dir == 'down' %}{{270.0|plus:AngularOffset}}
														{% elsif dir == 'both' and RightSided %}{{180.0|plus:AngularOffset}}
														{% elsif dir == 'both' and LeftSided %}{{0.0|plus:AngularOffset}}
														{% elsif dir == 'none' and RightSided %}{{0.0|plus:AngularOffset}}
														{% elsif dir == 'none' and LeftSided %}{{180.0|plus:AngularOffset}}
														{% else %}45.0
														{% endif %}

SymbolDefinition.BlockNameFormat:
NO-BN-2D-JBTSA_SIG-SIGNAL
{% if MainSignal == 'Hs1' or MainSignal == 'RepHs1' %}HS1
{% elsif MainSignal == 'Hs2' or MainSignal == 'RepHs2' %}HS2
{% elsif MainSignal == 'Hs3' %}HS3
{% endif %}
{% if DistantSignal == 'Yes' %}FS{% endif %}
{% if EndOfTrainRouteSignal == 'Yes' %}TVS{% endif %}
{% if DwarfSignal == 'Yes' %}DS{% endif %}
{% if HighShuntingSignal == 'Yes' %}ZS{% endif %}
{% if PositionLamp == 'Yes' %}MKS{% endif %}
{% if CautiousDrivingSignal == 'Yes' %}FKS{% endif %}
{% if LineSignal == 'Yes' %}LS{% endif %}
{% if OpticalSpeedSignal == 'Yes' %}LHS{% endif %}
{% if BrakeTestSignal == 'Yes' %}BPS{% endif %}
{% if DepartureSignal == 'Yes' %}AVS{% endif %}
{% if PortalMounted %}AAK{% endif %}
{{SymbolMode}}

Rotation.AddAngle:
{% if dir == 'up' %}{{270.0|plus:AngularOffset}}
														{% elsif dir == 'down' %}{{90.0|plus:AngularOffset}}
														{% elsif dir == 'both' and RightSided %}{{180.0|plus:AngularOffset}}
														{% elsif dir == 'both' and LeftSided %}{{0.0|plus:AngularOffset}}
														{% elsif dir == 'none' and RightSided %}{{0.0|plus:AngularOffset}}
														{% elsif dir == 'none' and LeftSided %}{{180.0|plus:AngularOffset}}
														{% else %}45.0
														{% endif %}

SymbolDefinition.BlockNameFormat:
NO-BN-2D-JBTSA_SIG-SIGNAL
{% if Variant == 'Level crossing, signal' %}HS2
{% elsif Variant == 'Level crossing, distant signal' %}HS2
{% else %}BAD_Variant_{{Variant}}
{% endif %}
{{SymbolMode}}

Rotation.AddAngle:
{% if dir == 'up' %}{{270.0|plus:AngularOffset}}
														{% elsif dir == 'down' %}{{90.0|plus:AngularOffset}}
														{% elsif dir == 'both' and RightSided %}{{180.0|plus:AngularOffset}}
														{% elsif dir == 'both' and LeftSided %}{{0.0|plus:AngularOffset}}
														{% elsif dir == 'none' and RightSided %}{{0.0|plus:AngularOffset}}
														{% elsif dir == 'none' and LeftSided %}{{180.0|plus:AngularOffset}}
														{% else %}45.0
														{% endif %}

SymbolDefinition.BlockNameFormat:
NO-BN-2D-JBTSA_SIG-VEISIGNAL
{% if Variant == 'Road signal/Single signal towards road' %}VS1
{% elsif Variant == 'Road signal/Double signal towards road' %}VS2
{% else %}BAD_Variant_{{Variant}}
{% endif %}
{% if PortalMounted %}AAK{% endif %}
{{SymbolMode}}
